latoryDomain": "32014L0024", "cbc:NoticeTypeCode": {"@listName": "competition", "#text": "cn-standard"}, "cbc:NoticeLanguageCode": {"@listName": "language", "#text": "FRA"}, "cac:ContractingParty": {"cbc:BuyerProfileURI": "https://marches.maximilien.fr/", "cac:ContractingPartyType": {"cbc:PartyTypeCode": {"@listName": "buyer-legal-type", "#text": "body-pl"}}, "cac:ContractingActivity": {"cbc:ActivityTypeCode": {"@listName": "authority-activity", "#text": "health"}}, "cac:Party": {"cac:PartyIdentification": {"cbc:ID": "ORG-0001"}}}, "cac:TenderingTerms": {"cac:TendererQualificationRequest": {"cac:SpecificTendererRequirement": {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "nati-ground"}}}, "cac:LotDistribution": {"cbc:MaximumLotsAwardedNumeric": "9", "cbc:MaximumLotsSubmittedNumeric": "9"}}, "cac:TenderingProcess": {"cbc:ProcedureCode": {"@listName": "procurement-procedure-type", "#text": "open"}}, "cac:ProcurementProject": {"cbc:ID": "2023-R055-L00-000", "cbc:Name": {"@languageID": "FRA", "#text": "PRESTATIONS DE TRAVAUX D'ENTRETIEN, DE RÉPARATION ET DE RÉAMÉNAGEMENT DE BATIMENT - PAYS DE LA LOIRE"}, "cbc:Description": {"@languageID": "FRA", "#text": "La présente consultation a pour objet la conclusion, par le Resah agissant en tant que centrale d'achat au titre de l'article L. 2113-2, 2° du Code, d'un accord-cadre à bons de commande ayant pour objet la réalisation d'opérations de travaux d'entretien, de réparation et de réaménagement de bâtiment.

Il couvre les travaux :
- d'entretien, de réparation, d'amélioration, de mise en conformité ou de maintien en l'état des bâtiments (bâti, locaux, réseaux) et des installations techniques intérieures et extérieures ;
- d'adaptation, d'aménagement courant, de réaménagement, de restructuration, de réhabilitation (remise en état profonde d'un ouvrage ancien impliquant une modification profonde des volumes ou une redistribution importante des espaces) et de réutilisation (changement d'affectation d'un ouvrage ancien) des bâtiments (bâti, locaux, réseaux) et des installations techniques intérieures et extérieures ;
- rendus nécessaires par des situations d'urgence (vol, dégradation volontaire ou non, incendie, inondation, tempêtes et autres sinistres) ou des dysfonctionnements techniques (pannes, fuites sur réseaux, coupures d'artères d'énergie, etc.) des bâtiments (bâti, locaux, réseaux) et des installations techniques intérieures et extérieures ;
- afférents au maintien de la sécurité des personnes et des biens.

Les opérations de travaux objet du présent accord-cadre sont exclues du champ d'application de la loi n°85-704 du 12 juillet 1985 modifiée relative à la maîtrise d'ouvrage publique et à ses rapports avec la maîtrise d'oeuvre privée et ses décrets et arrêtés d'application (dits loi « MOP » relative aux recours à une maitrise d'oeuvre extérieure), dorénavant codifiés dans le code de la commande publique."}, "cbc:ProcurementTypeCode": {"@listName": "contract-nature", "#text": "works"}, "cbc:Note": {"@languageID": "FRA", "#text": "Cette consultation fait suite à des lots infructueux. Ainsi les lots techniques 7, 9, 11 et 12 ont été attribués et le présent document ne concerne donc que les lots 1 à 6, 10 et 13."}, "cac:RequestedTenderTotal": {"ext:UBLExtensions": {"ext:UBLExtension": {"ext:ExtensionContent": {"efext:EformsExtension": {"efbc:FrameworkMaximumAmount": {"@currencyID": "EUR", "#text": "48132000"}}}}}, "cbc:EstimatedOverallContractAmount": {"@currencyID": "EUR", "#text": "12033000"}}, "cac:MainCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "45000000"}}, "cac:AdditionalCommodityClassification": [{"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "45421000"}}, {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "44111400"}}, {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "44112220"}}, {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "45432120"}}, {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "45311200"}}, {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "45261210"}}, {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "45223110"}}, {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "45421143"}}, {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "44316500"}}], "cac:RealizedLocation": {"cbc:Description": {"@languageID": "FRA", "#text": "Les prestations objet de l'Accord-cadre sont susceptibles d'être exécutées par le Titulai